# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a claim's amount, date, note, the number it corrects and its reference. Body as for an
# add; refused the same way (400), 404 for a claim not on the sheet, and 422 for a claim that is not a
# draft, whose due-by (kept by the edit) is inside a closed period, or whose editor another user has open (locked).
# Saving releases the user's lock on the claim.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  next: locked
  govern: [ transaction ]
locked:
  class: net.officefloor.hq.app.claim.RefuseLockedClaim
  next: draft
  govern: [ transaction ]
draft:
  class: net.officefloor.hq.app.claim.RefuseNonDraftClaim
  next: closed
  govern: [ transaction ]
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  next: retired
  govern: [ transaction ]
retired:
  class: net.officefloor.hq.app.claim.RefuseRetiredClaim
  next: correction
  govern: [ transaction ]
correction:
  class: net.officefloor.hq.app.claim.RefuseInvalidCorrectionClaim
  next: ref
  govern: [ transaction ]
